globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.acceptedAnswers ? {acceptedAnswers: row.acceptedAnswers} : {}),
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(row.textAnswer !== undefined ? {textAnswer: row.textAnswer} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(row.acceptedNumericAnswers ? {acceptedNumericAnswers: row.acceptedNumericAnswers} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + (group.originalNumbers ? group.start : 1)), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.solutionsFile ? {solutionUrl: folder + meta.solutionsFile} : {}),
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"subject":"kit","contest":"КИТ","language":"ru","letters":"АБВГД","count":30,"points":3,"solutionsFile":"solutions.pdf","year":2011,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"reviewed-8-9.pdf","readerFile":"8-9-reading.pdf","reviewedKey":true}, [{"title":"Визуальный вывод","question":"Какое количество устройств, представленных на рисунке, являются устройствами для вывода визуальной информации?","choices":["1","2","3","4","0"],"points":3,"steps":["Монитор выводит изображение на экран, принтер — на бумагу. Оба передают информацию, которую можно увидеть.","Клавиатура вводит данные, а колонки выводят звук. Подходят два устройства."],"answer":1,"figure":{"src":"assets/kit/2011/8-9-01.webp","alt":"Четыре компьютерных устройства."}},{"title":"Носители вирусов","question":"Компьютерные вирусы не распространяются через…","choices":["монитор","дискеты","веб-страницы","электронную почту","флэш-накопители"],"points":3,"steps":["Компьютерный вирус передаётся в виде данных. Съёмные накопители, почта и страницы могут доставлять на компьютер файлы.","Монитор показывает полученное от компьютера изображение, поэтому среди вариантов через него вирус не распространяется."],"answer":0},{"title":"Цена адаптера","question":"Wi-Fi адаптер и MP3-плеер вместе стоят 1600 рублей. Адаптер на 400 рублей дешевле плеера. Сколько рублей стоит адаптер?","choices":["400","600","800","1000","1200"],"points":3,"steps":["Если убрать из цены плеера разницу 400 рублей, он будет стоить столько же, сколько адаптер. В сумме получим 1600 − 400 = 1200.","Раздели 1200 между двумя равными ценами. Адаптер стоит 600 рублей, а плеер на 400 дороже: 1000 рублей."],"answer":1},{"title":"Год МЭСМ и теста Тьюринга","question":"В этом году осуществлён пробный запуск МЭСМ — советской ЭВМ, разработанной под руководством академика Сергея Алексеевича Лебедева и ставшей первой в СССР и континентальной Европе. С момента создания ЭНИАКа прошло всего четыре года. В том же году исследовательская организация в Миннеаполисе представила первый коммерческий компьютер ERA 1101, а английский математик Алан Тьюринг предложил тест для проверки, является ли компьютер разумным. 25 июня началась Корейская война, а президент США Гарри Трумэн заявил, что отдал приказ начать производство водородной бомбы. Это был…","choices":["1940 год","1950 год","1960 год","1970 год","1980 год"],"points":3,"steps":["Начало Корейской войны датируется 25 июня 1950 года. Это событие вместе с датами остальных подсказок позволяет отличить 1950-й от соседних десятилетий.","В 1950 году также была опубликована статья Тьюринга, в которой он предложил свой тест, и испытана советская МЭСМ."],"answer":1},{"title":"Зачем дефрагментировать диск","question":"Одной из целей дефрагментации является…","choices":["ускорение загрузки программ и файлов","нахождение заражённых вирусами файлов","удаление неиспользуемых файлов в корзину","разбиение картинки или фотографии на отдельные фрагменты","слияние в единый файл двух или нескольких файлов"],"points":3,"steps":["Если части файла разбросаны по механическому диску, считывающая головка должна несколько раз перейти на другие участки. Это занимает время.","При дефрагментации связанные участки файла переносятся ближе друг к другу. Для такого диска это может ускорить чтение файлов и запуск программ."],"answer":0},{"title":"Преобразование рисунка","question":"В графическом редакторе совершено преобразование рисунка, как показано ниже. Какая операция была использована?","choices":["отразить слева направо","повернуть по часовой стрелке","отразить сверху вниз","повернуть против часовой стрелки","свободное вращение"],"points":3,"steps":["Сравни верхние ряды: единственная тёмная клетка переместилась со второго места на третье. При этом верхний ряд остался верхним.","Внизу порядок четырёх клеток также стал обратным, но по высоте ничего не изменилось. Это отражение слева направо."],"answer":0,"figure":{"src":"assets/kit/2011/8-9-06.svg","alt":"Чёрно-белый рисунок до и после преобразования."}},{"title":"Комплектующие и устройства","question":"Установите соответствие.","choices":["1-e, 2-c, 3-d, 4-b, 5-a","1-d, 2-c, 3-e, 4-b, 5-a","1-e, 2-c, 3-b, 4-d, 5-a","1-c, 2-b, 3-e, 4-a, 5-d","1-c, 2-d, 3-e, 4-b, 5-a"],"points":3,"steps":["Магнитная головка считывает жёсткий диск, чипсет находится на материнской плате. Это пары 2-d и 3-e.","Принтер расходует картридж (4-b), копировальный аппарат использует фотовал (5-a), сетевую плату ставят в системный блок (1-c). Совпадает Д."],"answer":4,"context":"1. Системный блок\n2. Жёсткий диск\n3. Материнская плата\n4. Принтер\n5. Копировальный аппарат\n\na. Фотовал\nb. Картридж\nc. Сетевая плата\nd. Магнитная головка\ne. Чипсет"},{"title":"Старший из братьев","question":"В семье 5 братьев. Вася старше Коли, Саша младше Серёжи, Вася старше Володи и Серёжа младше Володи. Старшего брата зовут…","choices":["Вася","Володя","Коля","Саша","Серёжа"],"points":3,"steps":["Получается цепочка от старших к младшим: Вася, Володя, Серёжа, Саша.","Коля тоже младше Васи, хотя его место среди остальных неизвестно. Вася старше всех четверых."],"answer":0},{"title":"Назначение видеокарты","question":"Видеокартой может быть…","choices":["устройство, преобразующее графический образ в иную форму, предназначенную для дальнейшего вывода на экран монитора","графический редактор","программное обеспечение, преобразующее графический образ в иную форму, предназначенную для дальнейшего вывода на экран монитора","устройство, преобразующее звуковой образ в иную форму, предназначенную для дальнейшего вывода на колонки","пластиковая карта, позволяющая оплатить выход в Интернет, чтобы получить возможность просмотра видеофайлов"],"points":3,"steps":["Видеокарта отвечает за подготовку изображения для вывода на монитор. Значит, описание должно говорить об изображении, а не о звуке.","Видеокарта — физический компонент, поэтому подходит устройство из варианта А. Графический редактор и другое ПО выполняются на компьютере, но сами видеокартами не являются."],"answer":0},{"title":"Выражение по ячейкам","question":"Дана электронная таблица. Чему будет равно B2 + D1 / A1 + C3?","choices":["11","21","31","41","51"],"points":3,"steps":["Из таблицы B2 = 6, D1 = 4, A1 = 1 и C3 = 11. Сначала выполни деление 4 / 1.","Сложи 6 + 4 + 11. Получится 21."],"answer":1,"context":"Столбцы: A · B · C · D\nСтрока 1: 1 · 2 · 3 · 4\nСтрока 2: 5 · 6 · 7 · 8\nСтрока 3: 9 · 10 · 11 · 12\nСтрока 4: 13 · 14 · 15 · 16"},{"title":"Двухбуквенные номера дисков","question":"Петя пронумеровал все свои 100 дисков с помощью двухбуквенного кода, используя 33 буквы русского алфавита: АА, АБ, …, АЯ, БА, … . Какой номер имеет его последний диск?","choices":["ВА","КИ","ГА","ВЯ","ЯЯ"],"points":4,"steps":["При одной и той же первой букве можно выбрать 33 вторые буквы. Первые три полных набора с А, Б и В дадут 33 · 3 = 99 кодов.","После последнего кода ВЯ начинается набор с буквой Г. Сотый код — его первый элемент, ГА."],"answer":2},{"title":"Контрольная сумма пакета","question":"Выберите верный ответ. Контрольная сумма пакета данных при пересылке…","choices":["вычисляется только принимающим компьютером","вычисляется только передающим компьютером","не совпадает на принимающем и передающем компьютерах при корректной передаче данных","предназначена исключительно для нумерации пакетов","вычисляется на принимающем и передающем компьютерах"],"points":4,"steps":["Передающий компьютер вычисляет сумму из отправляемых данных, чтобы при приёме можно было проверить, не изменились ли они.","Принимающий компьютер снова вычисляет её из полученных данных и сравнивает с переданным значением. Поэтому работу выполняют обе стороны."],"answer":4},{"title":"Соседние члены ряда","question":"Найдите закономерность и определите следующий член последовательности: 2, 3, 6, 18, …","choices":["24","48","56","108","216"],"points":4,"steps":["Проверь первые числа: 2 · 3 = 6, а 3 · 6 = 18. Каждый новый член — произведение двух предыдущих.","Следующий член равен 6 · 18 = 108."],"answer":3},{"title":"Ряд устройств вывода","question":"Продолжите ряд: монитор, проектор, графопостроитель, …","choices":["принтер","процессор","клавиатура","трекбол","сканер"],"points":4,"steps":["Монитор показывает изображение на экране, проектор переносит его на стену, графопостроитель рисует на листе. Все устройства выводят видимый результат.","Принтер делает то же самое на бумаге. Клавиатура, трекбол и сканер вводят данные, а процессор обрабатывает их."],"answer":0},{"title":"Первая трещина на стекле","question":"Петя Геймеров очень любит стрелялки. Однажды во время игры ему потребовалось расстрелять окно. Оно не разбилось, а пошло трещинами, и на экране появился запрос: «Укажите отверстие, появившееся первым». Помогите ему указать верное отверстие.","choices":["1","2","3","4","5"],"points":4,"steps":["Поздняя трещина, дойдя до уже имеющейся, заканчивается у неё. Поэтому ищи, где трещины идут свободно, а другие в них упираются.","Трещины от отверстия 1 продолжаются, не упираясь в другие трещины. Это отверстие появилось раньше остальных."],"answer":0,"figure":{"src":"assets/kit/2011/8-9-15.svg","alt":"Пять пронумерованных отверстий и линии трещин."}},{"title":"Ошибка в цепочке равенств","question":"На классной доске записана цепочка равенств. Ошибка возникает при переходе к строке с номером…","choices":["6","2","3","4","5"],"points":4,"steps":["Квадрат числа всегда неотрицателен. Квадратный корень из t² равен модулю t, чтобы результат тоже был неотрицательным.","В строке 4 слева и справа получается 1/2. В строке 5 убрали модули и получили −1/2 = 1/2. Ошибка появилась в строке 5."],"answer":4,"context":"1. 16 − 36 = 25 − 45\n2. 16 − 36 + 81/4 = 25 − 45 + 81/4\n3. (4 − 9/2)² = (5 − 9/2)²\n4. √((4 − 9/2)²) = √((5 − 9/2)²)\n5. 4 − 9/2 = 5 − 9/2\n6. 4 = 5"},{"title":"Время в Перми и Москве","question":"Когда Коля Самолётов вылетал из Перми, часы аэровокзала показывали 12:00 местного времени. Прилетев в Москву, Коля увидел, что часы на московском аэровокзале показывают 12:00. Через неделю Коля полетел назад. Вылетев в 16:00 по московскому времени, он прилетел в Пермь в 20:00 по пермскому. Скольким часам равна разница во времени между Пермью и Москвой?","choices":["время совпадает","2","3","4","5"],"points":4,"steps":["Пусть полёт в каждом направлении занимает t часов и Пермь впереди на d часов. В первом полёте часы показали разницу 0, то есть t − d = 0.","На обратном пути разница 4 часа, то есть t + d = 4. Значит, t = d = 2 часа."],"answer":1,"context":"Для расчёта считайте, что время перелёта в обоих направлениях одинаково."},{"title":"Замена букв в тексте","question":"В текстовом редакторе набран приведённый текст. Команда для исправления ошибок должна иметь вид…","choices":["найти «АС», заменить на «АСТ»","найти «С», заменить на «СТ»","найти «АСН», заменить на «АСТН»","найти «СТ», заменить на «С»","найти «СН», заменить на «СТН»"],"points":4,"steps":["Слова «прекрастно» и «ужастно» получили лишнюю Т после С. Выбери замену, которая удалит её именно в сочетании СТ.","Если найти «СТ» и заменить на «С», получатся «прекрасно» и «ужасно». Остальные слова в этой фразе не изменятся."],"answer":3,"context":"НЕ ЧУДЕСНО, НЕ ПРЕКРАСТНО, А УЖАСТНО И ОПАСНО БУКВУ «Т» ПИСАТЬ НАПРАСНО!"},{"title":"Палиндромы на счётчике","question":"Программист Серёжа написал программу по проверке сбойных секторов на диске и увидел, что проверено 25952 сектора. Ровно через 2 секунды счётчик показал ближайшее следующее число, которое читается одинаково в обоих направлениях. Сколько секторов проверяется за секунду?","choices":["25","2","55","4","110"],"points":4,"steps":["Чтобы найти следующий палиндром, увеличь первые три цифры 259 до 260. Отрази две первые цифры в конец: получится 26062.","Проверили 26062 − 25952 = 110 новых секторов за две секунды. За секунду проверяют 55."],"answer":2},{"title":"Сортировка складской таблицы","question":"К таблице применили составную сортировку: сначала по возрастанию по столбцу «Ответственный», а затем по возрастанию по столбцу «Номенклатура». После этого на последней строке оказался товар по цене, равной…","choices":["10","100","200","500","1000"],"points":4,"steps":["Основной ключ сортировки — фамилия. Петров по алфавиту раньше Сидорова, значит, ищем последнюю строку в группе Сидорова.","Его товары по алфавиту: ключ, колесо, масло. Последним идёт масло стоимостью 200."],"answer":2,"context":"Номер · Номенклатура · Цена · Количество · Место · Ответственный\n1 · Колесо · 1000 · 2 · Склад №1 · Сидоров\n2 · Шина · 500 · 3 · Склад №2 · Петров\n3 · Масло · 200 · 2 · Склад №3 · Сидоров\n4 · Антифриз · 100 · 6 · Склад №2 · Петров\n5 · Ключ · 10 · 1 · Склад №1 · Сидоров"},{"title":"Книги в заданном порядке","question":"У Васи Чайникова пять книг: C++, C#, Pascal, Fortran и Java. Он хочет расставить их на полке так, чтобы книга по Java стояла первой, а книги по C++ и C# — рядом. Количество возможных вариантов расстановки равно…","choices":["12","6","8","10","5"],"points":5,"steps":["Java сразу занимает своё место. Считай соседние книги C++ и C# одной парой. Тогда остаются три переставляемых предмета: эта пара, Pascal и Fortran.","Их можно поставить 3 · 2 · 1 = 6 способами. Внутри пары две перестановки, поэтому всего 6 · 2 = 12."],"answer":0},{"title":"Вопросы о 25 билетах","question":"На экзамене по информатике присутствуют 25 учеников, каждый из которых получил один из 25 билетов. Учитель должен узнать, кто какой билет получил, и хочет задать как можно меньше вопросов. В каждом вопросе учитель перечисляет список номеров билетов от 1 до 25, ученики с билетами из списка поднимают руки. Минимальное количество вопросов равно…","choices":["3","5","7","10","15"],"points":5,"steps":["Ответ одного ученика на каждый вопрос имеет два значения: рука поднята или опущена. Четыре вопроса дают не более 2⁴ = 16 разных наборов, а номеров 25.","Запиши каждый номер пятью двоичными цифрами. В каждом из пяти вопросов назови номера с единицей на соответствующем месте. Набор поднятых рук однозначно показывает номер каждого ученика."],"answer":1},{"title":"Время в отражении часов","question":"Правильно идущие электронные часы отражаются в зеркале. Который сейчас час?","choices":["17:19","19:17","16:17","17:16","17:17"],"points":5,"steps":["Здесь зеркало находится сверху, поэтому порядок цифр слева направо сохраняется. Меняются местами верхние и нижние сегменты каждой цифры.","Отрази рисунок обратно: вторая цифра становится 9, а последняя — 7. Часы показывают 19:17."],"answer":1,"figure":{"src":"assets/kit/2011/8-9-23.svg","alt":"Отражённая индикация электронных часов."}},{"title":"Сколько кабелей с узлами","question":"Петя Шнуров работает в организации, проводящей сеть для предприятий. Однажды, достав сетевые кабели из сумки, он обнаружил следующую картину. Сколько кабелей завяжутся в узел, если аккуратно потянуть за концы в разные стороны?","choices":["1","2","3","4","5"],"points":5,"steps":["Проследи каждый кабель. У короткого разрыва линия уходит под другой участок. На столе можно повторить все пересечения шнурком.","Только у второго и третьего кабелей шнур продет через затягивающуюся петлю. Они образуют два узла."],"answer":1,"figure":{"src":"assets/kit/2011/8-9-24.svg","alt":"Пять кабелей со схемами пересечений."}},{"title":"Проследить x и y","question":"На вход программы, приведённой ниже, поданы два числа 1 и 3. Какие значения будут выведены в результате её работы?","choices":["9, 10","10, 9","7, 3","8, 8","3, 7"],"points":5,"steps":["Начни с x = 1, y = 3. Первая команда даёт x = 3 − 1 = 2, вторая y = 2 · 2 = 4.","С новыми значениями получаются x = 2 · 4 + 2 = 10 и y = 4 + 10 / 2 = 9. Выводятся 10 и 9."],"answer":1,"context":"Ввести x, y\nx := y − x\ny := 2*x\nx := 2*y + x\ny := y + x/2\nВывести x, y"},{"title":"Нули в конце произведения","question":"На какое количество нулей оканчивается произведение всех целых чисел от 5 до 25 включительно?","choices":["6","7","3","4","5"],"points":5,"steps":["Каждый ноль в конце получается от пары множителей 2 и 5. Двоек много, поэтому посчитай пятёрки.","Числа 5, 10, 15 и 20 дают по одной пятёрке, число 25 — две. Получается 6 пар и 6 нулей в конце."],"answer":0,"adaptation":"По официальному разбору уточнено, что нужно посчитать нули в конце произведения."},{"title":"Скриптовый язык","question":"Скриптовым языком программирования является…","choices":["МБ45","Pascal","Basic","Delphi","PHP"],"points":5,"steps":["PHP часто используют для сценариев, которые работают на сервере и формируют веб-страницы. Его программы запускаются под управлением среды исполнения.","В этом наборе PHP — скриптовый язык, а МБ45 — вообще не название языка программирования."],"answer":4},{"title":"Что вычисляет программа","question":"Дан фрагмент программы. После его выполнения значение выражения A + B при любых натуральных 32-битных целых A и B всегда будет равно…","choices":["НОД(A, B)","НОК(A, B)","наименьшему из чисел A или B","наибольшему из чисел A или B","ESET NOD32 (A, B)"],"points":5,"steps":["Замена большего числа на разность сохраняет общие делители: если число делит A и B, то оно делит A − B, и наоборот. При этом сумма положительных чисел каждый раз уменьшается.","Цикл остановится, когда одно число станет нулём. Тогда другое число равно общему делителю, который был наибольшим с начала. Сумма с нулём даёт НОД исходных A и B."],"answer":0,"context":"НЦ ПОКА A <> 0 И B <> 0\n  ЕСЛИ A > B ТО\n    A := A − B\n  ИНАЧЕ\n    B := B − A\n  ВСЕ\nКЦ"},{"title":"Норка между книгами","question":"Вася Чайников поставил на полку две книги: сначала «C++ для чайников», а справа от неё «C# для чайников». Толщина каждой книги без учёта обложки составляет 20 мм, толщина обложки — 3 мм. Книжный червь прогрыз норку от первой страницы «C++ для чайников» до последней страницы «C# для чайников». Сколько миллиметров составляет длина норки?","choices":[],"points":5,"steps":["Смотри на книги со стороны корешков. Первая страница левой книги граничит с правой обложкой. Последняя страница правой книги граничит с левой обложкой.","Эти обложки соприкасаются. Червь прогрыз только две толщины обложки, 3 + 3 = 6 мм."],"numericAnswer":6,"figure":{"src":"assets/kit/2011/8-9-29.webp","alt":"Две книги на полке корешками к зрителю."}},{"title":"Гирька на прилавке","question":"У продавца восемь внешне одинаковых гирек массой 1, 2, 3, 4, 5, 6, 7 и 8 граммов. Продавец положил несколько гирек на одну чашу весов и несколько на другую так, что чаши уравнялись, а одна гирька осталась на прилавке. После этого покупатель смог однозначно определить её массу. Сколько граммов весит оставшаяся гирька?","choices":[],"points":5,"steps":["Общая масса 36 г. Равные чаши содержат вместе чётное число граммов, поэтому осталась гирька 2, 4, 6 или 8 г. Одна гиря против шести уравновеситься не может.","При распределении 3 против 4 все четыре массы возможны. Примеры равновесия для оставшихся 2, 4, 6 и 8 г: 3 + 6 + 8 = 1 + 4 + 5 + 7, 1 + 7 + 8 = 2 + 3 + 5 + 6, 3 + 4 + 8 = 1 + 2 + 5 + 7, 1 + 6 + 7 = 2 + 3 + 4 + 5.","Остаются две гири против пяти. Если отбросить 2 или 4 г, на чаше нужно 17 или 16 г, больше суммы 7 + 8. Если убрать 8 г, на чаше нужно 14 г, больше суммы 6 + 7. При 6 г имеем 7 + 8 = 1 + 2 + 3 + 4 + 5. Оставшаяся гирька весит 6 г."],"numericAnswer":6}]);
